( function( $ ) {
	let windowWidth = $(window).width();
	$.fn.DiviModalPopupRemoveClasses = function( orderClass ) {
		let $this   = this,
		$classes    = el_modal_popup_get_module_classes();

		$classes.push(orderClass);
		$this.removeClass( $classes.join(' ') );

		$this.css( {
			'animation-delay'           : '',
			'animation-duration'        : '',
			'animation-timing-function' : '',
			'opacity'                   : '',
			'transform'                 : '',
			'filter'                    : '',
		} );
		return this;
	};
	
	$.fn.DiviModalPopup = function( options ) {
		let defaults = {
			action: '',
			href: '#',
			delay: '0',
		};
		
		let $modal   = this,
			$timeOut = 0,
			$options = $.extend({}, defaults, options);

		if ( 'undefined' !== typeof( $modal.find('.el_modal_popup_inner_wrap').data('animation-duration') ) ) {
			$timeOut = parseFloat( $modal.find('.el_modal_popup_inner_wrap').data('animation-duration') );
			if ( windowWidth < 981 ) {
				if ( 'undefined' !== typeof( $modal.find('.el_modal_popup_inner_wrap').data('animation-duration-tablet') ) && '' !== $modal.find('.el_modal_popup_wrapper').data('animation-duration-tablet') ) {
					$timeOut = parseFloat( $modal.find('.el_modal_popup_inner_wrap').data('animation-duration-tablet') );
				}
			} else if ( windowWidth < 768 ) {
				if ( 'undefined' !== typeof( $modal.find('.el_modal_popup_inner_wrap').data('animation-duration-phone') ) && '' !== $modal.find('.el_modal_popup_wrapper').data('animation-duration-phone') ) {
					$timeOut = parseFloat( $modal.find('.el_modal_popup_inner_wrap').data('animation-duration-phone') );
				}
			}
		}

		if ( 'open' === $options.action ) {
			let delay = parseInt( $options.delay );
			setTimeout( function() {

				$('body').find('.el_modal_popup').removeClass('el_modal_popup_active_modal');
				$('body').addClass('el_modal_popup_active');
				$modal.addClass('el_modal_popup_active_modal');

				/* The wrapper was just unhidden (display:none -> flex) in this same
				   tick, so its subtree has never been laid out. Force a reflow before
				   triggering the entrance animation on the first open, otherwise the
				   browser has no "before" frame to animate from and just snaps to the
				   end state instantly. */
				void $modal.find('.el_modal_popup_wrapper')[0].offsetWidth;

				if ( 'off' === $modal.find('.el_modal_popup_wrapper').data('disable-website-scroll') ) {
					$('body').addClass('el_modal_popup_enable_scroll');
				}
				setTimeout( function() {
					$('body').find('.el_modal_popup').removeClass('el_modal_popup_opened');
					$modal.addClass('el_modal_popup_opened');
				}, $timeOut );
				setTimeout( function() {
					el_modal_popup_autoplay_video( $modal );
				}, ( 0.7 * $timeOut ) );

				el_modal_popup_trigger_entrance_animation( $modal );
				$(document).trigger( 'diviModalPopupOpened' );
			}, delay);
		}
 
		if ( 'close' === $options.action ) {
			let modalId     = $modal.prop( 'id' ),
				triggerType = $modal.find( '.el_modal_popup_wrapper' ).data( 'trigger-type' ),
				reRender    = $modal.find( '.el_modal_popup_wrapper' ).data( 're-render' );

			if ( 0 !== $timeOut ) {
				$modal.addClass( 'el_modal_popup_closing' );
				$modal.removeClass( 'el_modal_popup_active_modal' );
				$modal.removeClass( 'el_modal_popup_opened' );

				/* Force a reflow on the animated element so the browser restarts
				   its (already finished) entrance animation in reverse, instead of
				   treating the animation-direction change as a no-op. Only touch
				   animation-name here (not the 'animation' shorthand) so we don't
				   clobber the animation-duration/delay/timing-function inline
				   styles that Divi's own animateElement() already set on open. */
				let $animatedEls = $modal.find( '.el_modal_popup_animated' );
				if ( $animatedEls.length > 0 ) {
					$animatedEls.css( 'animation-name', 'none' );
					void $animatedEls[0].offsetWidth;
				}
				$modal.addClass( 'el_modal_popup_animate_reverse' );
				if ( $animatedEls.length > 0 ) {
					$animatedEls.css( 'animation-name', '' );
				}

				$( 'body' ).removeClass( 'el_modal_popup_enable_scroll' );
				$( 'body' ).removeClass( 'el_modal_popup_active' );
				if ( $options.href && '#' !== $options.href ) {
					window.location.href = $options.href;
				}
				setTimeout( function() {
					$modal.removeClass( 'el_modal_popup_animate_reverse' );
					$modal.removeClass( 'el_modal_popup_closing' );
				}, $timeOut );
			} else {
				$modal.removeClass( 'el_modal_popup_active_modal' );
				$modal.removeClass( 'el_modal_popup_opened' );
				$( 'body' ).removeClass( 'el_modal_popup_active' );
				$( 'body' ).removeClass( 'el_modal_popup_enable_scroll' );
				if ( $options.href && '#' !== $options.href ) {
					window.location.href = $options.href;
				}
			}
			
			el_modal_popup_stop_video($modal);
			if ( -1 !== $.inArray( triggerType, [ 'exit_intent', 'on_page_load', 'on_scroll', 'user_inactivity' ] ) ) {
				let modalStorageKey = modalId + '_' + triggerType + '_hide';
				if ( ( 'on_page_load' === triggerType && 'off' === reRender ) || ( 'exit_intent' === triggerType && 'off' === reRender ) || 
					 ( 'on_scroll' === triggerType && 'off' === reRender ) || ( 'user_inactivity' === triggerType && 'off' === reRender ) ) {
					sessionStorage.setItem( modalStorageKey, 'true' );
				}
				if ( ( 'exit_intent' === triggerType && 'on' === reRender ) || ( 'on_scroll' === triggerType && 'on' === reRender ) ) {
					$modal.find('.el_modal_popup_wrapper').data('rendered', 'yes');
				}
			}
			if ( $options.href && '#' !== $options.href ) {
				window.location.href = $options.href;
			}

			$(document).trigger( 'diviModalPopupClosed' );
		}
		return this;
	};

	if ( $('body').find('.el_modal_popup').length > 0 ) {

		let $user_inactivity_modals = {};
		$('body').find('.el_modal_popup').each( function() {
			let $this               = $(this),
				$modalClass         = $this.prop('class'),
				$orderClass         = $this.prop('class').match(/el_modal_popup_\d+/)[0],
				$modalId            = $this.find('.el_modal_popup_wrapper').data('id'),
				$modalStorageKey    = $modalId + '_' + $this.find('.el_modal_popup_wrapper').data('trigger-type') + '_hide',
				$modal_container    = $('<div class="el_modal_popup_section entry-content et_pb_section et-l"></div>'),
				$modal              = $('<div></div>');

			$modal.prop( 'id', $modalId );
			$modal.prop( 'class', $modalClass );
			$modal.DiviModalPopupRemoveClasses($orderClass).addClass('el_modal_popup_module');
			
			if ( $this.hasClass( $orderClass + '_tb_header' ) ) {
				$modal.addClass( $orderClass + '_tb_header_module' );
			} else if ( $this.hasClass( $orderClass + '_tb_body' ) ) {
				$modal.addClass( $orderClass + '_tb_body_module' );
			} else if ( $this.hasClass( $orderClass + '_tb_footer' ) ) {
				$modal.addClass( $orderClass + '_tb_footer_module' );
			} else {
				$modal.addClass( $orderClass + '_module' );
			} 

			$modal.html( $(this).find('.el_modal_popup_wrapper').detach() );
			$modal_container.html($modal);

			if ( $('body').find('#page-container').find('#et-boc').length > 0 ) {
				$('body').find('#page-container').find('#et-boc').append( $modal_container );
			} else if ( $('body').find('#page-container').length > 0 ) {
				$('body').find('#page-container').append( $modal_container );
			} else if ( $('body').find('#et_builder_outer_content').length > 0 ) {
				$('body').find('#et_builder_outer_content').append( $modal_container );
			} else if ( $('body').find('#et-boc').length > 0 ) {
				$('body').find('#et-boc').append( $modal_container );
			} else {
				$('body').append( $modal_container );
			}

			if ( $('body').find('.el_modal_popup_body .el_modal_popup_close').length > 0 ) {
				$('body').find('.el_modal_popup_body .el_modal_popup_close').each(function(){
					if ( $(this).attr('href') ) {
						$(this).attr('data-href', $(this).attr('href'));
						$(this).attr('href', '#');
					}
				});
			}

			if ( 'none' === $this.css('display') ) {
				return;
			}
			
			if ( 'element' === $modal.find('.el_modal_popup_wrapper').data('trigger-type') ) {
				if ( 'undefined' !== typeof( $modal.find('.el_modal_popup_wrapper').data('trigger-element-id') ) && '' !== $modal.find('.el_modal_popup_wrapper').data('trigger-element-id') ) {
					/* Trigger modal on user defined element */
					let $elem = '#' + $modal.find('.el_modal_popup_wrapper').data('trigger-element-id');
					$('body').on('click', $elem, function(e){
						e.preventDefault();
						$modal.DiviModalPopup({
							action: 'open',
						});
					});
				} else if ( 'undefined' !== typeof( $modal.find('.el_modal_popup_wrapper').data('trigger-element-class') ) && '' !== $modal.find('.el_modal_popup_wrapper').data('trigger-element-class') ) {
					/* Trigger modal on user defined element */
					let $elem = '.' + $modal.find('.el_modal_popup_wrapper').data('trigger-element-class');
					$('body').on('click', $elem, function(e){
						e.preventDefault();
						$modal.DiviModalPopup({
							action: 'open',
						});
					});
				} else if ( $this.find('.el_modal_popup_trigger_element').length > 0 ) {
					/* Trigger modal on modal trigger element */
					$this.find('.el_modal_popup_trigger_element').on('click', function(e){
						e.preventDefault();
						$modal.DiviModalPopup({
							action: 'open',
						});
					});
				}
			} else if ( 'on_page_load' === $modal.find('.el_modal_popup_wrapper').data('trigger-type') ) {
				/* Trigger modal on page load */
				let delay       = parseFloat( $modal.find('.el_modal_popup_wrapper').data('trigger-delay') ),
					reRender    = $modal.find('.el_modal_popup_wrapper').data('re-render');
					if ( ( 'off' === reRender && 'true' !== sessionStorage.getItem( $modalStorageKey ) ) || 'on' === reRender ) {
						$modal.DiviModalPopup({
							action: 'open',
							delay: delay,
						});
					}
			} else if ( 'exit_intent' === $modal.find('.el_modal_popup_wrapper').data('trigger-type') ) {
				/* Trigger modal on exit intent */
				let reRender = $modal.find('.el_modal_popup_wrapper').data('re-render');
				$(document).on('mouseout', function(e) {
					if ( ! $modal.hasClass('el_modal_popup_opened') ) {
						if ( 
							( e.toElement == null && e.relatedTarget == null && ( 'off' === reRender && 'true' !== sessionStorage.getItem( $modalStorageKey ) ) ) ||
							( e.toElement == null && e.relatedTarget == null && 'on' === reRender && 'yes' !== $modal.find('.el_modal_popup_wrapper').data('rendered') )
						) {
							$modal.DiviModalPopup({
								action: 'open',
							});
						}
					}
				});
			} else if ( 'on_scroll' === $modal.find('.el_modal_popup_wrapper').data('trigger-type') ) {
				/* Trigger modal on scroll */
				let docHeight = $('body').outerHeight(),
					scrollPos = $modal.find('.el_modal_popup_wrapper').data('scroll-position'),
					reRender  = $modal.find('.el_modal_popup_wrapper').data('re-render');
					if ( scrollPos.includes('%') ) {
						scrollPos = ( parseFloat( scrollPos )/100 ) * ( parseFloat( docHeight ) - $(window).outerHeight(true) );
					}
					scrollPos = parseFloat( scrollPos );
				$(window).on('scroll', function(e) {
					let scrollY = $(window).scrollTop();
					if ( ! $modal.hasClass('el_modal_popup_opened') ) {
						if ( 
							( 'off' === reRender && 'true' !== sessionStorage.getItem( $modalStorageKey ) && scrollY >= scrollPos ) ||
							( 'on' === reRender && 'yes' !== $modal.find('.el_modal_popup_wrapper').data('rendered') && scrollY >= scrollPos )
						) {
							$modal.DiviModalPopup({
								action: 'open',
							});
						}
					}
				});
			} else if ( 'user_inactivity' === $modal.find('.el_modal_popup_wrapper').data('trigger-type') ) {
				// Get the timeout
				let reRender             = $modal.find('.el_modal_popup_wrapper').data('re-render'),
					user_inactivity_time = parseInt( $modal.find('.el_modal_popup_wrapper').data('user-inactivity-time') );

				// Add to the timer
				$user_inactivity_modals[$orderClass] = { 'modal_obj': $modal, 'modalstoragekey': $modalStorageKey, 'timer': '' };
				if ( ! $modal.hasClass('el_modal_popup_opened') ) {
					if ( ( 'off' === reRender && 'true' !== sessionStorage.getItem( $modalStorageKey ) ) || 'on' === reRender ) {
						$user_inactivity_modals[$orderClass]['timer'] = setTimeout( function() {
							$modal.DiviModalPopup( {
								action: 'open',
							} );
						}, (user_inactivity_time * 1000) );
					}
				}
			}
		} );

		// Reset user models, on user does activity.
		const events = [ 'load', 'mousemove', 'mousedown', 'touchstart', 'touchmove', 'click', 'keydown', 'scroll' ];
		events.forEach( s => window.addEventListener( s, user_inactivity_time_reset, true ) );
		function user_inactivity_time_reset() {
			$.each( $user_inactivity_modals, function( key, um ) {
				// Reset timer if already saved.
				if ( um.timer && '' !== um.timer ) {
					clearTimeout( um.timer );
				}

				// Check the models.
				const $modal = ( um.modal_obj ) ? um.modal_obj : '';
				if ( $modal ) {
					// Get the timeout.
					let reRender             = $modal.find('.el_modal_popup_wrapper').data('re-render'),
						user_inactivity_time = parseInt( $modal.find('.el_modal_popup_wrapper').data('user-inactivity-time') ),
						$modalStorageKey     = ( um.modalstoragekey ) ? um.modalstoragekey : '';

					if ( ! $modal.hasClass('el_modal_popup_opened') ) {
						if ( ( 'off' === reRender && 'true' !== sessionStorage.getItem( $modalStorageKey ) ) || 'on' === reRender ) {
							$user_inactivity_modals[key]['timer'] = setTimeout( function() {
								$modal.DiviModalPopup( {
									action: 'open',
								} );
							}, (user_inactivity_time * 1000) );
						}
					}
				}
			} );
		}

		/* Prevent modal closing before it's fully rendered */
		$('body').on( 'click', '.el_modal_popup_close', function(e){
			e.preventDefault();
		} );

		/* Close modal on outside click */
		$('body').on('click', '.el_modal_popup_opened .el_modal_popup_close_on_background_click', function(e){
			if ( $(e.target).is( $(this) ) ) {
				let $modal = $(this).parents('.el_modal_popup');
				$modal.DiviModalPopup({
					action: 'close',
				});
			}
		});
		
		/* Close modal on close icon click after its fully rendered */
		$('body').on('click', '.el_modal_popup_opened .el_modal_popup_close', function(e){
			e.preventDefault();
			let $modal = $(this).parents('.el_modal_popup'),
				$href  = $(this).attr('href');
			$modal.DiviModalPopup({
				action: 'close',
				href: $href,
			});
		});

		/* Close modal on esc key after its fully rendered */
		$(document).on('keyup', function(e){
			if ( e.keyCode === 27 ) {
				if ( 
					$('body').hasClass('el_modal_popup_active') &&
					$('body').find('.el_modal_popup_opened .el_modal_popup_wrapper').hasClass('el_modal_popup_close_on_esc') &&
					$('body').find('.el_modal_popup_opened .el_modal_popup_wrapper').length > 0
				) {
					let $modal = $('body').find('.el_modal_popup_opened');
					$modal.DiviModalPopup({
						action: 'close',
					});
				}
			}
		});

		if ( document.onfullscreenchange === null ) {
			document.onfullscreenchange = el_modal_popup_on_full_screen_change;
		} else if ( document.onmsfullscreenchange === null ) {
			document.onmsfullscreenchange = el_modal_popup_on_full_screen_change;
		} else if ( document.onmozfullscreenchange === null ) {
			document.onmozfullscreenchange = el_modal_popup_on_full_screen_change;
		} else if ( document.onwebkitfullscreenchange === null ) {
			document.onwebkitfullscreenchange = el_modal_popup_on_full_screen_change;
		}
	}

	function el_modal_popup_trigger_entrance_animation( $modal ) {
		if ( typeof et_animate_element === 'function' ) {
			et_animate_element( $modal.find( '.el_modal_popup_inner_wrap' ) );
		} else {
			$modal.find( '.el_modal_popup_inner_wrap' ).removeClass( 'et_animated' );
		}
	}

	function el_modal_popup_stop_video($modal) {
		if ( typeof($modal) === 'undefined' || '' === $modal ) {
			return false;
		}

		if ( $modal.find('iframe').length > 0 ) {
			let src = $modal.find('iframe').attr('src').replace('?autoplay=1&amp;', '?').replace('?autoplay=1&', '?').replace('?autoplay=1', '').replace('&amp;autoplay=1', '').replace('&autoplay=1', '').replace('&mute=1&muted=1', '');
			$modal.find('iframe').attr('src', src );
		} else if ( $modal.find('video').length > 0 ) {
			$modal.find('video').get(0).pause();
			$modal.find('video').get(0).currentTime = 0;
		}
	}

	function el_modal_popup_autoplay_video($modal) {
		if ( typeof($modal) === 'undefined' || '' === $modal ) {
			return false;
		}

		if ( 'on' === $modal.find('.el_modal_popup_wrapper').data('autoplay-video') ) {
			if ( $modal.find('iframe').length > 0 ) {
				let mute = 'on_page_load' === $modal.find('.el_modal_popup_wrapper').data('trigger-type') ? true : false;
				let src = el_modal_popup_add_autoplay_to_url( $modal.find('iframe').attr('src'), mute );
				$modal.find('iframe').attr('src', src );
			} else if ( $modal.find('video').length > 0 ) {
				let promise = $modal.find('video').get(0).play();
				if ( promise !== undefined ) {
					promise.then(_ => {
					}).catch(error => {
						$modal.find('video').prop('muted', true);
						$modal.find('video').get(0).play();
					});
				}
			}
		}
	}

	function el_modal_popup_add_autoplay_to_url(src, mute) {
		let uri     = decodeURIComponent( src );
		let atts    = uri.split('&');
		if ( 1 === atts.length ) {
			atts = uri.split('?');
			if ( 1 !== atts.length ) {
				uri = uri + '&autoplay=1';
				if ( mute ) {
					uri = uri + '&mute=1&muted=1';
				}
			} else {
				uri = uri + '?autoplay=1';
				if ( mute ) {
					uri = uri + '&mute=1&muted=1';
				}
			}
		} else {
			uri = uri + '&autoplay=1';
			if ( mute ) {
				uri = uri + '&mute=1&muted=1';
			}
		}
		return uri;
	}

	function el_modal_popup_get_module_classes() {
		return [
			'et_pb_sticky_module', 'et_pb_sticky',
			'et_pb_sticky--top', 'et_pb_sticky--bottom', 'et_pb_sticky--top_bottom',
			'et_animated', 'infinite', 'et-waypoint', 'et_had_animation',
			'fade', 'fadeTop', 'fadeRight', 'fadeBottom', 'fadeLeft',
			'slide', 'slideTop', 'slideRight', 'slideBottom', 'slideLeft',
			'bounce', 'bounceTop', 'bounceRight', 'bounceBottom', 'bounceLeft',
			'zoom', 'zoomTop', 'zoomRight', 'zoomBottom', 'zoomLeft',
			'flip', 'flipTop', 'flipRight', 'flipBottom', 'flipLeft',
			'fold', 'foldTop', 'foldRight', 'foldBottom', 'foldLeft',
			'roll', 'rollTop', 'rollRight', 'rollBottom', 'rollLeft', 'transformAnim',
		];
	}

	function el_modal_popup_on_full_screen_change() {
		let dmpFullScreenElement =
			document.fullscreenElement ||
			document.msFullscreenElement ||
			document.mozFullScreenElement ||
			document.webkitFullscreenElement;

			if ( !! dmpFullScreenElement ) {
				jQuery('body').find('.el_modal_popup_active_modal .el_modal_popup_inner_wrap').addClass('el_modal_popup_fullscreen');
			} else {
				jQuery('body').find('.el_modal_popup_module .el_modal_popup_inner_wrap').removeClass('el_modal_popup_fullscreen');
			}
	}
 
}( jQuery ));